 await officeCheck('calendar loaded for the selected year does not auto-fetch on render or month navigation','native current-year cache; browser request deduplication',async h=>{h.seed();h.c.flowPage();await h.flush();assert.equal(h.requests.length,1);await h.resolve(undefined,response([calendarFixture]));h.c.flowPage();h.c.changeOfficeMonth(1);h.c.flowPage();assert.equal(h.requests.length,1);assert.equal(h.queued.length,0)},'officecalendar');
 await officeCheck('optional-session nearby and calendar reads can run without logging in','operation registry optionalSession read contracts',async h=>{h.state.authenticated=false;h.state.user=null;h.seed();h.c.flowPage();await h.flush();assert.equal(h.requests.length,1);assert.equal(h.requests[0].options.body.operationId,OPERATIONS.find(op=>op.endpoint==='KantorNearby/GetCalendar').id);await h.resolve(undefined,response([]));assert.equal(h.state.authenticated,false);assert.equal(h.toasts.length,0)},'officecalendar');
 await officeCheck('navigation cancels busy tokens while preserving reusable office rows and selection','browser cached shared-state lifecycle',async h=>{h.seed();h.c.openOfficeItem(0);const selected=h.owner.selected,pending=h.c.loadNearbyOffices();h.c.location.hash='#/officecalendar';h.c.navigate();assert.equal(h.owner.loading,false);assert.equal(h.owner.locationBusy,false);assert.equal(h.owner.request,null);assert.equal(h.owner.detailOpen,false);assert.equal(h.owner.selected,selected);await h.resolve(pending,response([{...officeFixture,namaKantor:'Stale'}]));assert.equal(h.owner.selected,selected);assert.equal(h.owner.rows[0].namaKantor,officeFixture.namaKantor)});
 observations.functions=helpers;
